import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Research Intelligence System V1.0","description":"","frontmatter":{"title":"Research Intelligence System V1.0","outline":"deep"},"headers":[],"relativePath":"en/runtime/research-intelligence.md","filePath":"en/runtime/research-intelligence.md","lastUpdated":1786174465000}'),i={name:"en/runtime/research-intelligence.md"};function o(l,e,s,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="research-intelligence-system-v1-0" tabindex="-1">Research Intelligence System V1.0 <a class="header-anchor" href="#research-intelligence-system-v1-0" aria-label="Permalink to &quot;Research Intelligence System V1.0&quot;">​</a></h1><h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p>The Research Intelligence System separates where evidence is discovered from what the Research Center studies:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Three intelligence pipelines</span></span>
<span class="line"><span>→ unified and deduplicated signal pool</span></span>
<span class="line"><span>→ three permanent research columns</span></span></code></pre></div><h2 id="intelligence-sources-情报源地图" tabindex="-1">Intelligence Sources / 情报源地图 <a class="header-anchor" href="#intelligence-sources-情报源地图" aria-label="Permalink to &quot;Intelligence Sources / 情报源地图&quot;">​</a></h2><p>This page gives a plain-language bilingual map of the main sources monitored by the Digital Researcher. The complete machine-readable Watchlist in <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/REGISTRY.json" target="_blank" rel="noreferrer"><code>research/intelligence/REGISTRY.json</code></a> remains the single source of truth.</p><h3 id="ai-platforms-ai-平台" tabindex="-1">AI Platforms / AI 平台 <a class="header-anchor" href="#ai-platforms-ai-平台" aria-label="Permalink to &quot;AI Platforms / AI 平台&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Plain-language description</th><th>Frequency</th><th>Main focus</th></tr></thead><tbody><tr><td>OpenAI</td><td>OpenAI official product, developer and research channels / OpenAI 官方产品、开发与研究入口</td><td>P0 · Daily</td><td>ChatGPT, Codex, API, Agents, enterprise controls</td></tr><tr><td>Anthropic / Claude</td><td>Anthropic and Claude official channels / Anthropic 与 Claude 官方信息</td><td>P0 · Daily</td><td>Claude, Claude Code, API, agent governance</td></tr><tr><td>Google / Gemini</td><td>Google Gemini official developer and product channels / Google Gemini 官方开发与产品信息</td><td>P0 · Daily</td><td>Gemini API, AI Studio, Vertex AI, Gemini CLI, ADK</td></tr><tr><td>Cursor</td><td>Cursor official coding and agent platform / Cursor 官方开发工具与 Agent 平台</td><td>P0 · Daily</td><td>Coding Agents, Cloud Agents, CLI, engineering workflows</td></tr><tr><td>GitHub Copilot</td><td>GitHub official AI coding product / GitHub 官方 AI 编程产品</td><td>P0 · Daily</td><td>Copilot, Coding Agent, CLI, Code Review</td></tr><tr><td>Microsoft Copilot Platform</td><td>Microsoft enterprise Copilot and agent platform / 微软 Copilot 与企业 Agent 平台</td><td>P0 · Daily</td><td>Microsoft 365 Copilot, Copilot Studio, Agent Builder, Power Platform</td></tr></tbody></table><h3 id="github-engineering-repositories-github-工程仓库" tabindex="-1">GitHub Engineering Repositories / GitHub 工程仓库 <a class="header-anchor" href="#github-engineering-repositories-github-工程仓库" aria-label="Permalink to &quot;GitHub Engineering Repositories / GitHub 工程仓库&quot;">​</a></h3><p><strong>P0 · Daily</strong></p><table tabindex="0"><thead><tr><th>Repository</th><th>Plain-language description</th><th>Main focus</th></tr></thead><tbody><tr><td><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">openai/codex</a></td><td>OpenAI Codex engineering repository / OpenAI Codex 开源工程仓库</td><td>Coding Agent, runtime, sandbox, permissions, review, protocols</td></tr><tr><td><a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">openai/openai-agents-python</a></td><td>OpenAI Agents Python SDK</td><td>Agent SDK, tools, handoffs, tracing, runtime mechanisms</td></tr><tr><td><a href="https://github.com/anthropics/claude-code" target="_blank" rel="noreferrer">anthropics/claude-code</a></td><td>Anthropic Claude Code engineering repository</td><td>Coding Agent, tools, permissions, sessions, recovery</td></tr><tr><td><a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noreferrer">google-gemini/gemini-cli</a></td><td>Google Gemini CLI</td><td>CLI agents, tools, execution environment, interaction protocols</td></tr><tr><td><a href="https://github.com/google/adk-python" target="_blank" rel="noreferrer">google/adk-python</a></td><td>Google Agent Development Kit for Python</td><td>Agent framework, workflows, tools, runtime</td></tr><tr><td><a href="https://github.com/github/copilot-cli" target="_blank" rel="noreferrer">github/copilot-cli</a></td><td>GitHub Copilot CLI</td><td>Terminal agents, coding workflows, execution and permissions</td></tr><tr><td><a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noreferrer">modelcontextprotocol/python-sdk</a></td><td>MCP Python SDK</td><td>Model Context Protocol Python implementation</td></tr><tr><td><a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">modelcontextprotocol/typescript-sdk</a></td><td>MCP TypeScript SDK</td><td>Model Context Protocol TypeScript implementation</td></tr><tr><td><a href="https://github.com/a2aproject/A2A" target="_blank" rel="noreferrer">a2aproject/A2A</a></td><td>Agent2Agent protocol project</td><td>Agent interoperability, task and message boundaries</td></tr></tbody></table><p>The Registry also maintains P1 weekly repositories including AutoGen, Semantic Kernel, LangGraph, CrewAI, OpenHands, browser-use, SWE-bench, SWE-agent, Langfuse and Phoenix.</p><h3 id="published-research-论文与研究成果" tabindex="-1">Published Research / 论文与研究成果 <a class="header-anchor" href="#published-research-论文与研究成果" aria-label="Permalink to &quot;Published Research / 论文与研究成果&quot;">​</a></h3><p><strong>P0 · Daily</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>Plain-language bilingual description</th><th>Main focus</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a></td><td>Open scholarly preprint platform / 开放学术预印本平台</td><td><code>cs.MA</code>, <code>cs.SE</code>, <code>cs.AI</code></td></tr><tr><td><a href="https://link.springer.com/journal/10458" target="_blank" rel="noreferrer">Autonomous Agents and Multi-Agent Systems</a></td><td>JAAMAS, a peer-reviewed multi-agent systems journal / 《自主智能体与多智能体系统》期刊</td><td>Multi-Agent, organization, coordination, protocols, governance</td></tr><tr><td><a href="https://www.sciencedirect.com/journal/journal-of-systems-and-software" target="_blank" rel="noreferrer">Journal of Systems and Software</a></td><td>JSS, a peer-reviewed software engineering journal / 《系统与软件》期刊</td><td>Software architecture, engineering, empirical evaluation, reproducibility</td></tr><tr><td><a href="https://zenodo.org/" target="_blank" rel="noreferrer">Zenodo</a></td><td>Open research-output and DOI repository / 开放科研成果与 DOI 存档平台</td><td>Software, datasets, artifacts, reproducibility evidence</td></tr><tr><td><a href="https://openreview.net/" target="_blank" rel="noreferrer">OpenReview</a></td><td>Open peer-review platform / 开放同行评审平台</td><td>Papers, public reviews, conference research</td></tr><tr><td><a href="https://openai.com/research/" target="_blank" rel="noreferrer">OpenAI Research</a></td><td>OpenAI official research / OpenAI 官方研究</td><td>Agents, models, systems, safety, technical reports</td></tr><tr><td><a href="https://www.anthropic.com/research" target="_blank" rel="noreferrer">Anthropic Research</a></td><td>Anthropic official research / Anthropic 官方研究</td><td>Agents, safety, model behavior, governance</td></tr><tr><td><a href="https://deepmind.google/research/" target="_blank" rel="noreferrer">Google DeepMind Research</a></td><td>Google DeepMind official research / Google DeepMind 官方研究</td><td>Agents, AI systems, models, frontier research</td></tr><tr><td><a href="https://www.microsoft.com/en-us/research/" target="_blank" rel="noreferrer">Microsoft Research</a></td><td><strong>Microsoft&#39;s official research organization / 微软研究院、微软官方研究机构</strong></td><td>Agent systems, enterprise AI, software engineering, systems architecture, benchmarks</td></tr></tbody></table><p><strong>P1 · Weekly</strong> additionally includes ACL Anthology, PMLR, NeurIPS Proceedings, ACM Digital Library and IEEE Xplore.</p><blockquote><p>Principle: formal Daily Discovery sources should prefer public endpoints that do not depend on private login state. Restricted full text is recorded as an access condition rather than being treated as absence of a research object.</p></blockquote><h2 id="intelligence-skills" tabindex="-1">Intelligence skills <a class="header-anchor" href="#intelligence-skills" aria-label="Permalink to &quot;Intelligence skills&quot;">​</a></h2><h3 id="ai-platform-change-intelligence" tabindex="-1">AI Platform Change Intelligence <a class="header-anchor" href="#ai-platform-change-intelligence" aria-label="Permalink to &quot;AI Platform Change Intelligence&quot;">​</a></h3><p>Daily monitoring of official release notes, documentation, forums or communities, API changes, enterprise controls, status pages and official GitHub sources.</p><h3 id="github-engineering-intelligence" tabindex="-1">GitHub Engineering Intelligence <a class="header-anchor" href="#github-engineering-intelligence" aria-label="Permalink to &quot;GitHub Engineering Intelligence&quot;">​</a></h3><p>A controlled, incremental engineering radar covering fixed watchlists, releases, tags, merged PRs, high-value issues, discussions, security advisories, checkpoint-based scanning and bounded exploration.</p><h3 id="published-research-intelligence" tabindex="-1">Published Research Intelligence <a class="header-anchor" href="#published-research-intelligence" aria-label="Permalink to &quot;Published Research Intelligence&quot;">​</a></h3><p>Papers, preprints, technical reports, benchmarks, datasets, system or model cards, specifications and their associated code and evaluation artifacts.</p><h2 id="three-research-columns" tabindex="-1">Three research columns <a class="header-anchor" href="#three-research-columns" aria-label="Permalink to &quot;Three research columns&quot;">​</a></h2><p>All pipelines serve Digital Employee, Industry Architecture and Open-source Engineering. One change has one primary column and optional secondary impact.</p><h2 id="daily-completion-gate" tabindex="-1">Daily completion gate <a class="header-anchor" href="#daily-completion-gate" aria-label="Permalink to &quot;Daily completion gate&quot;">​</a></h2><p>The 10:00 Queue shift must report source coverage, inaccessible channels, failures, signal and candidate counts, and a Selected or No Selection decision for every column.</p><p>“Checked with no important change” is different from “not checked.”</p><h2 id="authoritative-artifacts" tabindex="-1">Authoritative artifacts <a class="header-anchor" href="#authoritative-artifacts" aria-label="Permalink to &quot;Authoritative artifacts&quot;">​</a></h2><ul><li>Registry: <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/REGISTRY.json" target="_blank" rel="noreferrer"><code>research/intelligence/REGISTRY.json</code></a></li><li>Daily Run: <code>research/intelligence/runs/YYYY/MM/YYYY-MM-DD-intelligence.json</code></li><li>Skill Profiles: <code>research/skills/profiles/</code></li></ul>`,31)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
